 scene.background=new THREE.Color(course>=4?EXPANSIONS[course].sky:course===3?0x30232c:course===2?0x0b3543:0x0b2034);
 // Only menu preview uses reduced fog and enhanced light; racing rebuilds own world.
 scene.fog=new THREE.FogExp2(course>=4?EXPANSIONS[course].fog:course===3?0x453034:course===2?0x0b3543:0x0e263b,course>=4?.000095:course===3?.00019:course===2?.00098:.00031);
