 previewTime+=dt;
 const movieTime=reduced?0:previewTime;
 const s=menuCamera(track,course,camera,movieTime,world,reduced),reel=camera.userData.menuReel;
 const curtain=$('#menuReelCurtain');
 if(curtain){const opacity=reel?.fade||0;if(Math.abs(opacity-(curtain._lastOpacity??-1))>.018){curtain.style.opacity=String(opacity);curtain._lastOpacity=opacity;}}
 const label=$('#menuReelStatus');if(label&&reel){const value='LIVE CINEMATIC · '+String(reel.shot+1).padStart(2,'0')+'/04';if(label.textContent!==value)label.textContent=value;}
