 hudText('#obsModeLabel',explorer.mode==='fly'?'AUTOMATIC FLYTHROUGH':explorer.mode==='chase'?'CLOSE INSPECTION':explorer.mode==='overhead'?'TOP-DOWN SURVEY':'LIVE WORLD ORBIT');
 hudText('#obsDescription',explorer.mode==='fly'?'Following the real course · '+Math.round(track.length)+'m':explorer.mode==='orbit'?'Real level scenery · drag to rotate or choose an act':explorer.mode==='overhead'?'Overhead route survey · pinch to zoom':'Inspect actual track obstacle placements');
