function openExplorer(){
 if(state!=='menu'||garage||!window.shiftlineReady||!$('#observatory').classList.contains('off'))return;
 // Reuse the exact rendered race environment; do not construct a second world.
 if(!world||!track||!scene)return;
 effects?.dispose();effects=null;
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.2));
 renderer.shadowMap.enabled=false;
 setWorldDetail(scene,world,$('#quality').value==='low'?'low':'auto');
 if(player)player.visible=false;
 for(const o of menuHazards)o.rig.visible=false;
 try{
   // Actual animated race hazards: world geometry is already resident, and
   // gameplay's normal distance culling limits rendered objects.
   specs=buildObstacles(scene,track,course);
   explorer=createTrackExplorer(track,scene,world,specs);
 }catch(error){
   console.error('Observatory unavailable',error);
   if(specs.length){disposeObstacles(scene,specs);specs=[];}
   if(player)player.visible=true;
   renderer.shadowMap.enabled=true;renderer.setPixelRatio(Math.min(devicePixelRatio,qualityRatio()));
   setWorldDetail(scene,world,$('#quality').value);
   effects=new RaceEffects(renderer);return;
 }
 $('#obsTitle').textContent=TRACKS[course].name;
 $('#observatory').style.setProperty('--obsAccent',TRACKS[course].color);
 for(const btn of document.querySelectorAll('[data-obs-chapter]')){
  const index=+btn.dataset.obsChapter,act=actAt(track.length*(index+.25)/4,track.length,course);
  btn.querySelector('span').textContent=act.name.replace(/^0[1-4] \/ /,'');
 }
 
 $('#menu').classList.add('off');$('#observatory').classList.remove('off');
 resetExplorer(explorer);seekExplorer(explorer,.08);refreshObservatory(true);
 renderDeadline=0;lastFrame=performance.now();
}
function openGarage(){disposeRace();renderer.toneMappingExposure=1.15;if(effects?.final?.uniforms?.exposure)effects.final.uniforms.exposure.value=1;garage=createGarage(readProgress());renderer.shadowMap.enabled=true;document.querySelectorAll('[data-garage-light]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.garageLight==='studio')));}
