function combatActors(){return [{id:mode==='online'?myId:'you',s:along,x,y,speed,dead:!!dead,finished:state==='finished'},...(mode==='online'?[...remote.entries()].map(([id,r])=>({id,s:r.target?.t??r.s,x:r.target?.x??r.x,y:r.target?.y??r.y,speed:r.target?.speed||0,dead:!!r.target?.crashed,finished:r.finished})):rivals.map(r=>({id:'ai'+r.id,s:r.s,x:r.x,y:r.y,speed:r.speed,dead:!!r.dead,finished:r.s>=track.length})))];}
function initCombat(){fireHeld=false;weapon='pulse';combatSeq=0;lastCombatSend=-10;hitSlowUntil=0;combatHits=combatKills=0;hudText('#combatScore','HITS 0 · KILLS 0');$('#hitMarker').style.opacity=0;const active=variant==='combat'||variant==='training';$('#combatHUD').classList.toggle('off',!active);document.body.classList.toggle('combatActive',active);document.body.dataset.raceMode=active?'battle':variant;hudText('#modeBadge',active?'BATTLE':variant==='trial'?'TIME TRIAL':variant==='tour'?'FLIGHT':'RACE');if(!active)return;const ships=[[mode==='online'?myId:'you',player],...(mode==='online'?[...remote.entries()].map(([id,r])=>[id,r.mesh]):rivals.map(r=>['ai'+r.id,r.mesh]))];combatCore=new Combat(track.length,ships.map(p=>p[0]),course);combatView=createCombatView(scene,track,ships);}
function combatAction(action){if(!combatCore||state!=='race'||paused||dead)return;const id=mode==='online'?myId:'you';if(mode==='online'){if(socket?.readyState!==1)return;socket.send(JSON.stringify({type:action==='defence'?'defence':'fire',weapon}));}else{if(action==='defence')combatCore.defence(id);else combatCore.fire(id,weapon,combatActors());}}
function combatStep(dt){if(!combatCore||state!=='race')return;const actors=combatActors();if(mode==='solo'){combatCore.step(dt,actors);for(const r of rivals){const id='ai'+r.id,f=combatCore.fighters.get(id),a=actors.find(p=>p.id===id);if(r.dead||a.finished)continue;const target=combatCore.target(actors,a);if(target)combatCore.fire(id,f.missiles>0&&time%7<2?'missile':'pulse',actors);if(f.mines>0&&actors.some(q=>q.id!==id&&a.s-q.s>6&&a.s-q.s<18)&&time%8<.15)combatCore.fire(id,'mine',actors)}processCombatEvents(combatCore.events)}const me=actors[0],f=combatCore.fighters.get(me.id);const canPulse=weapon!=='pulse'||f?.coolUntil<=combatCore.time;if(!dead&&(fireHeld||keys.has('f'))&&canPulse&&time-lastCombatSend>(weapon==='pulse'?WEAPONS.pulse.cooldown:weapon==='missile'?.4:.5)){combatAction('fire');lastCombatSend=time;}}
function processCombatEvents(events){for(const e of events||[]){if(e.seq<=combatSeq)continue;combatSeq=e.seq;const id=mode==='online'?myId:'you';if(e.type==='shot'&&e.shot.owner===id)weaponSound(e.shot.weapon);if(e.type==='overheat'&&e.id===id){uiSound()}if(e.type==='hit'){shieldHit(combatView,e.id,time);if(e.owner===id&&e.id!==id){hitSound();combatHits++;hudText('#hitCount','×'+combatHits);$('#hitMarker').style.opacity=1;$('#hitMarker').dataset.until=String(performance.now()+200);hudText('#combatScore','HITS '+combatHits+' · KILLS '+combatKills)}if(e.id===id){shieldSound(e.shield>0);hitSlowUntil=time+.28;boost=false;}}if(e.type==='destroyed'){if(e.owner===id&&e.id!==id){hitSound(true);combatKills++;hudText('#combatScore','HITS '+combatHits+' · KILLS '+combatKills);message('KILL CONFIRMED / '+combatKills,'#ffce95',2)}if(e.id===id){dead=Math.max(dead,.95);impactStarted=time;boost=false;fireHeld=false;crashes++;burstImpact(impacts,track.pose(along,x,y),track.frame(along),time,course===2,course);crashSound();}else if(mode==='solo'){const r=rivals.find(r=>'ai'+r.id===e.id);if(r){r.dead=Math.max(r.dead,.95);r.impactStarted=time;burstImpact(impacts,track.pose(r.s,r.x,r.y),track.frame(r.s),time,course===2,course)}}}if(e.type==='pickup'&&e.id===id){passSound(3);}if(e.type==='defence'){shieldHit(combatView,e.id,time);if(e.id===id){shiftSound();}}}}
function receiveCombat(m){if(!combatCore||mode!=='online'||variant!=='combat'||!m.snapshot||m.snapshot.seq<combatSeq)return;const data=m.snapshot;if(!Array.isArray(data.fighters)||!Array.isArray(data.shots)||!Array.isArray(data.taken))return;combatCore.time=data.time;combatCore.seq=data.seq;combatCore.fighters=new Map(data.fighters.map(f=>[f.id,f]));combatCore.shots=data.shots;const taken=new Set(data.taken);for(const p of combatCore.pickups)p.taken=taken.has(p.id);processCombatEvents(m.events);const f=combatCore.fighters.get(myId);if(f?.recover>data.time&&state==='race'){dead=Math.max(dead,Math.min(.95,f.recover-data.time));boost=false;}}
function renderCombat(view){if(!combatCore||!combatView)return;updateCombatView(combatView,combatCore,along,time);const id=mode==='online'?myId:'you',f=combatCore.fighters.get(id);if(!f)return;hudText('#shieldValue','SHIELD '+Math.round(f.shield));hudText('#hullValue','HULL '+Math.round(f.hull));hudText('#weaponStatus',weapon==='pulse'?'PULSE / '+(PULSE_LIMIT-(f.pulseShots||0))+' / '+PULSE_LIMIT:weapon==='missile'?'HOMING / '+f.missiles:'MINE / '+f.mines);hudText('#autoShield',f.defence>combatCore.time?'SHIELD ACTIVE':'AUTO SHIELD '+f.defences);$('#combatVitals').style.setProperty('--shield',String(Math.max(0,f.shield)/60));$('#combatVitals').style.setProperty('--hull',String(Math.max(0,f.hull)/100));$('#fire').dataset.weapon=weapon;const cooling=Math.max(0,(f.coolUntil||0)-combatCore.time),heat=cooling?cooling/PULSE_COOLING:(f.pulseShots||0)/PULSE_LIMIT;$('#pulseHeat i').style.transform='scaleX('+heat+')';$('#pulseHeat').classList.toggle('cooling',cooling>0);hudText('#heatStatus',cooling?'COOLING / '+cooling.toFixed(1)+'s':'PULSE / '+(f.pulseShots||0)+' OF '+PULSE_LIMIT);$('#fire').classList.toggle('cooling',weapon==='pulse'&&cooling>0);updatePulseSight(pulseSight,$('#pulseSight'),track,camera,view||{s:along,x,y},{active:weapon==='pulse'&&!dead&&!paused&&state==='race'&&!$('#combatHUD').classList.contains('off'),cooling:cooling>0,firing:fireHeld||keys.has('f'),width:innerWidth,height:innerHeight});const actors=combatActors(),candidate=weapon==='missile'?combatCore.target(actors,actors[0]):null;updateMissileLock(actors,candidate,f);const name={pulse:'PULSE',missile:'HOMING',mine:'MINE'}[weapon],ready=weapon==='pulse'?!cooling:weapon==='missile'?f.missiles>0&&!!candidate:f.mines>0;hudText('#fireLabel',name+'\n'+(weapon==='pulse'&&cooling?'COOLING':ready?'HOLD TO FIRE':weapon==='missile'&&f.missiles?'NO TARGET':'RECHARGING'));$('#fire').classList.toggle('unready',!ready);$('#fire').classList.toggle('firing',ready&&!dead&&!paused&&state==='race'&&(fireHeld||keys.has('f')));const recharge=weapon==='missile'&&f.missileReady?.length?Math.ceil(f.missileReady[0]-combatCore.time):weapon==='mine'&&f.mineReady?Math.ceil(f.mineReady-combatCore.time):0;if(recharge>0)hudText('#weaponStatus',name+' / '+(weapon==='missile'?f.missiles:f.mines)+' / READY '+recharge+'s');for(const k of ['pulse','missile','mine']){const node=$('#wheel'+k),count=k==='pulse'?PULSE_LIMIT-(f.pulseShots||0):k==='missile'?f.missiles:f.mines;hudText('#wheel'+k+'Label',{pulse:'PULSE',missile:'HOMING',mine:'MINE'}[k]+'\n'+(count===0&&k==='missile'&&f.missileReady?.length?Math.ceil(Math.max(0,f.missileReady[0]-combatCore.time))+'s':count===0&&k==='mine'&&f.mineReady?Math.ceil(Math.max(0,f.mineReady-combatCore.time))+'s':count+'/'+(k==='pulse'?PULSE_LIMIT:k==='missile'?2:1)));node.classList.toggle('selected',k===weapon);}}

function updateMissileLock(actors,candidate,f){const marker=$('#missileLock'),id=mode==='online'?myId:'you';const tracking=combatCore.shots.find(p=>p.weapon==='missile'&&p.owner===id&&p.target),target=weapon==='missile'&&f.missiles>0?candidate:weapon==='missile'&&tracking?actors.find(a=>a.id===tracking.target):null;const mesh=target&&(mode==='online'?remote.get(target.id)?.mesh:rivals.find(r=>'ai'+r.id===target.id)?.mesh);const hide=()=>marker.classList.add('off');if(!target||!mesh?.visible||dead||paused||state!=='race')return hide();lockPoint.copy(mesh.position);camera.updateMatrixWorld();camera.getWorldDirection(lockDirection);if(lockNDC.copy(lockPoint).sub(camera.position).dot(lockDirection)<=0)return hide();lockNDC.copy(lockPoint).project(camera);if(!Number.isFinite(lockNDC.x)||!Number.isFinite(lockNDC.y)||lockNDC.z< -1||lockNDC.z>1||Math.abs(lockNDC.x)>.94||Math.abs(lockNDC.y)>.84)return hide();const distance=lockPoint.distanceTo(camera.position),size=clamp(520/Math.max(8,distance),38,72);marker.style.left=((lockNDC.x+1)*innerWidth*.5)+'px';marker.style.top=((1-lockNDC.y)*innerHeight*.5)+'px';marker.style.width=marker.style.height=size+'px';marker.dataset.target=target.id;marker.classList.toggle('tracking',!(candidate&&f.missiles>0));marker.classList.remove('off');const name=mode==='online'?(roomPlayers.find(p=>p.id===target.id)?.name||'RACER'):'RIVAL '+(Number(target.id.slice(2))+1);hudText('#lockLabel',(candidate&&f.missiles>0?'LOCKED':'TRACKING')+' / '+name);hudText('#lockDistance',Math.round(Math.max(0,target.s-actors[0].s))+'m');}
function toggleBoost(){if(state!=='race'||paused||dead)return;if(boost)boost=false;else if(energy>2)boost=true;if(variant==='tour')tourThink=0;}
function selectWeapon(next){if(!['pulse','missile','mine'].includes(next))return;weapon=next;$('#fire').dataset.weapon=next;$('#combatHUD').style.setProperty('--weapon-color',{pulse:'#a5efff',missile:'#ffce91',mine:'#d9b6ff'}[next]);fireHeld=false;firePointer=null;lastCombatSend=-10;const items=['pulse','missile','mine'],at=items.indexOf(next);for(let i=0;i<3;i++){$('#wheel'+items[i]).style.setProperty('--slot',String((i-at+3)%3));$('#wheel'+items[i]).dataset.slot=String((i-at+3)%3);$('#wheel'+items[i]).classList.toggle('selected',items[i]===next)}renderCombat();}
function bindCombat(){const button=$('#fire');button.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();if(state==='race'&&!paused&&firePointer===null){firePointer=e.pointerId;fireHeld=true;button.setPointerCapture?.(e.pointerId)}});for(const event of['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,e=>{if(e.pointerId===firePointer){fireHeld=false;firePointer=null}});for(const k of ['pulse','missile','mine'])$('#wheel'+k).onclick=e=>{e?.stopPropagation();selectWeapon(k)};window.addEventListener('keydown',e=>{if(!e.repeat&&state==='race'){if(e.key==='q')selectWeapon(['pulse','missile','mine'][(['pulse','missile','mine'].indexOf(weapon)+1)%3]);}});$('#onlineMode').onchange=()=>{const active=$('#onlineMode').value==='combat';$('#onlineCourse').disabled=false};}

const trainingText=['','Drag left, right, up and down. Keyboard: arrows or WASD.','Tap BOOST to engage. Tap it again to cancel.','Fly through a glowing ring. Tight apertures award more boost. Impact? Retry and take another line.','Hold PULSE to fire 20 shots. Release to stop. The weapon then cools for 3 seconds.'];
function setupTraining(){const ring=specs.find(o=>o.solids.some(p=>p.type==='torus'));const removed=specs.filter(o=>o!==ring);disposeObstacles(scene,removed);specs=ring?[ring]:[];training={phase:1,directions:new Set(),engaged:false,cancelled:false,ring,done:false};$('#trainingHUD').classList.remove('off');enterTrainingPhase();}
function enterTrainingPhase(){const t=training;if(!t)return;if(t.phase>4){finishRace();return}t.retry=false;t.directions.clear();t.engaged=t.cancelled=false;dead=0;boost=false;energy=40;fireHeld=false;target={x:0,y:0};x=y=vx=vy=0;passed.clear();failed.clear();ringPasses.clear();nearGaps.clear();passes=0;along=t.phase===3&&t.ring?Math.max(8,t.ring.s-90):8;speed=t.phase===3?42:0;$('#trainingPrompt').textContent=t.phase+' / 4 · '+trainingText[t.phase];$('#trainingNext').textContent='SKIP LESSON';$('#trainingRetry').classList.toggle('off',t.phase!==3);$('#combatHUD').classList.toggle('off',t.phase!==4);document.body.classList.toggle('combatActive',t.phase===4);if(t.phase===4){combatCore.fighters.get('you').pulseShots=0;combatCore.fighters.get('you').coolUntil=0;} }
function trainingStep(){const t=training;if(t.done)return;if(t.phase===1){if(x<-.8)t.directions.add('left');if(x>.8)t.directions.add('right');if(y<-.8)t.directions.add('down');if(y>.8)t.directions.add('up');$('#trainingProgress').textContent=t.directions.size+' / 4 directions';if(t.directions.size===4){t.phase++;enterTrainingPhase()}}else if(t.phase===2){if(boost)t.engaged=true;if(t.engaged&&!boost)t.cancelled=true;$('#trainingProgress').textContent=t.engaged?'Tap again to cancel':'Tap BOOST';if(t.cancelled){t.phase++;enterTrainingPhase()}}else if(t.phase===3){$('#trainingProgress').textContent='Clean ring pass / +16 or +24 boost';if(t.retry&&!dead)enterTrainingPhase();else if(passes){if($('#energy').dataset.rewardText?.includes('RING')){t.phase++;enterTrainingPhase()}else enterTrainingPhase()}}else if(t.phase===4){const f=combatCore.fighters.get('you');$('#trainingProgress').textContent=(f.pulseShots||0)+' / 20 shots';if(f.coolUntil>combatCore.time){t.phase++;finishRace()}}}
